rule.definition:
a!localVariables(
  local!queryDataSubset:#"SYSTEM_SYSRULES_queryEntity_v1"(
    entity: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3192412",
    query: #"SYSTEM_SYSRULES_query"(
      selection: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!columns),
        {},
        #"SYSTEM_SYSRULES_querySelection"(
          columns: #"SYSTEM_SYSRULES_forEach"(
            items: ri!columns,
            expression: #"SYSTEM_SYSRULES_queryColumn"(field:fv!item)
          )
        )
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        ignorefilterswithemptyvalues: true,
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "requestId", 
            operator: "=", 
            value: ri!requestId, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "createdBy", 
            operator: "=", 
            value: ri!createdBy
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "createdOn", 
            operator: ">=", 
            value: ri!createdOn, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "version", 
            operator: "=", 
            value: ri!version, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "moduleTypeId", 
            operator: "=", 
            value: ri!moduleTypeId, 
          )
        }
      ),
      paginginfo: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!pagingInfo),
        #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1,
          sort: {
            #"SYSTEM_SYSRULES_sortInfo"(
              field: "auditId",
              ascending: true
            )
          },
        ),
        ri!pagingInfo
      )
    )
  ),
  if(
    ri!returnCDT,
    cast(
      'type!{urn:com:appian:types:CAW}CAW_Audit?list',
      local!queryDataSubset.data
    ),
    local!queryDataSubset
  )
)
